INSERT INTO `berita` (`id_berita`, `id_user`, `id_kategori`, `updater`, `slug_berita`, `judul_berita`, `isi`, `status_berita`, `jenis_berita`, `keywords`, `gambar`, `icon`, `hits`, `urutan`, `tanggal_mulai`, `tanggal_selesai`, `tanggal_post`, `tanggal_publish`, `tanggal`) VALUES
(9, 1, 5, '', 'ketua-kud-tenera-mukti-mandiri-menghadiri-ajang-tunamen-bola-kaki-di-lapangan-desa-indrapuri', 'Ketua KUD Tenera Mukti Mandiri menghadiri ajang Tunamen Bola Kaki di lapangan Desa Indrapuri', '<p>Koperasi Unit Desa Tenera Mukti Mandiri</p>', 'Publish', 'Berita', 'Berita ke 1', '309145218_2553738794756782_4560264617099992823_n.jpg', '', 5, 1, NULL, NULL, '2024-12-14 15:35:28', '2024-12-14 15:32:21', '2025-02-03 08:52:47'),
(10, 1, 5, '', 'pemindahan-pupuk-ke-gudang', 'Pemindahan Pupuk ke Gudang', '<p>Koperasi Unit Desa Tenera Mukti Mandiri</p>', 'Publish', 'Berita', 'Berita 2', 'Kartu_Foto_Beberapa_Foto_Pribadi_Gaya_Modern_Biru_Muda.jpg', '', 2, 2, NULL, NULL, '2024-12-14 15:37:57', '2024-12-14 15:36:15', '2025-02-03 08:52:28'),
(11, 1, 5, '', 'pendaftaran-anggota', 'Pendaftaran Anggota', '<p>silahkan isi form formulir pendaftaran secara offline</p>', 'Publish', 'Layanan', 'Cara Bergabung Dengan KUD', 'bary.jpg', '', 36, 1, NULL, NULL, '2024-12-14 15:42:40', '2024-12-14 15:41:14', '2025-02-03 08:55:08'),
(4, 1, 5, '', 'sejarah-singkat-kud-tmm', 'Sejarah Singkat KUD TMM', '<p>KUD Tenera Mukti Mandiri memiliki perjalanan yang dimulai sejak <strong>April 1994</strong> dengan nama awal <strong>KUD Tenera Mukti</strong>. Sebagai Koperasi Unit Desa, koperasi ini dibentuk untuk mendukung kesejahteraan anggota dan masyarakat desa sekitar melalui pengelolaan perkebunan plasma.</p>\r\n<p>Pada <strong>Oktober 2023</strong>, terjadi perubahan nama koperasi ini menjadi <strong>KUD Tenera Mukti Mandiri</strong>, berdasarkan <strong>akta perubahan</strong> yang disahkan oleh <strong>Kementerian Koperasi Republik Indonesia</strong>. Penambahan kata \"Mandiri\" pada nama koperasi mencerminkan komitmen koperasi untuk terus beroperasi secara independen dan profesional.</p>\r\n<p>Awalnya, luas plasma yang dikelola koperasi adalah <strong>932 hektar</strong>, namun saat ini menjadi <strong>928 hektar</strong> karena <strong>4 hektar</strong> dialihkan menjadi kebun milik warga. Dari sisi keanggotaan, jumlah anggota plasma yang awalnya <strong>466 anggota</strong>, kini berjumlah <strong>464 anggota</strong>. Koperasi juga menaungi <strong>21 kelompok tani</strong>, dengan tambahan <strong>11 orang</strong> yang tergabung sebagai anggota non-kelompok tani (non-poktan).</p>\r\n<p>Perubahan nama dan struktur ini diharapkan dapat semakin memperkuat peran KUD Tenera Mukti Mandiri dalam mengembangkan ekonomi dan mendukung kesejahteraan masyarakat desa serta para anggotanya.</p>', 'Publish', 'Profil', '', 'download1.JPG', '', 40, 1, NULL, NULL, '2019-07-26 10:38:15', '2024-12-12 10:36:47', '2025-02-12 14:21:02'),
(14, 1, 7, '', 'daftar-unit-usaha', 'Daftar Unit Usaha', '<p>Daftar Unit Usaha KUD Tenera Mukti Mandiri</p>\r\n<ol>\r\n<li>Unit Simpan&nbsp; Pinjam</li>\r\n<li>Unit Koserda</li>\r\n<li>Unit Sarana Produksi</li>\r\n<li>Unit Angkutan</li>\r\n<li>Pangkalan Gas</li>\r\n</ol>', 'Publish', 'Profil', 'Unit Usaha', NULL, '', 10, 5, NULL, NULL, '2024-12-14 15:50:49', '2024-12-14 15:49:54', '2025-02-03 08:48:02'),
(15, 1, 5, '', 'rapat-anggota-tahunan-koperasi-unit-desa-tenera-mukti-mandiri-tahun-2023', 'Rapat Anggota Tahunan Koperasi Unit Desa Tenera Mukti Mandiri Tahun 2023', '<p>Koperasi Unit Desa Tenera Mukti Mandiri</p>', 'Publish', 'Berita', 'Berita 3', 'Coklat_Minimalis_Moderen_Kolase_Foto_Sampul_Facebook.jpg', '', 7, 1, NULL, NULL, '2024-12-15 16:31:25', '2024-12-15 16:28:24', '2025-02-12 14:22:18'),
(16, 1, 7, '', 'tim-pendiri', 'Tim Pendiri', '<p><strong>Tim pendiri :</strong></p>\r\n<p><strong>Ketua Pertama KUD Tenera Mukti Mandiri: Bapak ESSARTO (1994-1996)</strong></p>\r\n<p><strong>Ketua Kedua KUD Tenera Mukti Mandiri: Bapak JUMIRIN (1996-1998)</strong></p>\r\n<p><strong>Ketua Ketiga KUD Tenera Mukti Mandiri: Bapak MANSUR NASUTION (1998-2003)</strong></p>\r\n<p><strong>Ketua Keempat KUD Tenera Mukti Mandiri: Bapak MAULANA SHOLEH (2003-2014)</strong></p>\r\n<p><strong>Ketua Kelima KUD Tenera Mukti Mandiri: Bapak MISPAR (2014-2018)</strong></p>\r\n<p><strong>Ketua Keenam KUD Tenera Mukti Mandiri: Bapak JUNAIDI (2018-2024)</strong></p>', 'Publish', 'Profil', '', NULL, '', 17, 2, NULL, NULL, '2025-01-13 20:07:11', '2025-01-13 20:06:14', '2025-02-12 14:21:38'),
(17, 1, 5, '', 'struktur-organisasi', 'Struktur Organisasi', '<p>Struktur Organisasi Koperasi Unit Desa Tenera Mukti Mandiri</p>', 'Publish', 'Profil', '', 'Neutral_Beige_Minimalist_Corporate_Company_Organizational_Chart_(1).jpg', '', 19, 4, NULL, NULL, '2025-01-13 20:11:37', '2025-01-13 20:10:28', '2025-02-12 14:21:57'),
(8, 1, 5, '', 'visi-misi', 'VISI MISI', '<p>Visi:</p>\r\n<p><strong>Memperkuat Ekonomi Petani Desa</strong></p>\r\n<p>Misi:</p>\r\n<p><strong>Tetap Menjaga Ekosistem untuk Sawit Berkelanjutan</strong></p>', 'Publish', 'Profil', '', 'f0c23161-b8f5-43cc-a272-4549308aeb051.JPG', '', 12, 2, NULL, NULL, '2024-12-12 20:36:15', '2024-12-12 20:35:14', '2025-02-12 14:21:47');
